package edu.hfut.access.service.impl;
import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;import com.fasterxml.jackson.databind.ObjectMapper;import edu.hfut.access.dao.AccessMapper;import edu.hfut.access.dao.IssuanceMapper;import edu.hfut.access.client.*;import edu.hfut.access.dto.Context;import edu.hfut.access.exception.ApiException;import static edu.hfut.access.security.Identity.*;
@Service public class IssuanceService{
 private final AccessMapper dao;private final IssuanceMapper operations;private final AppointmentClient appointments;private final DirectoryClient users;private final ObjectMapper json;@Value("${P4_INTERNAL_KEY}")String key;
 public IssuanceService(AccessMapper d,IssuanceMapper o,AppointmentClient a,DirectoryClient u,ObjectMapper j){dao=d;operations=o;appointments=a;users=u;json=j;}
 private Map<String,Object>map(Object...p){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<p.length;i+=2)m.put(String.valueOf(p[i]),p[i+1]);return m;}
 private String digest(Map<String,Object>b){try{return Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(new TreeMap<>(b))));}catch(Exception e){throw new IllegalStateException();}}
 private Map<String,Object>qr(String id){for(Map<String,Object>q:dao.list("qr_codes"))if(id.equals(q.get("id")))return q;return null;}
 public Map<String,Object>result(String id){Map<String,Object>op=operations.one(id);return op==null?map("found",false):map("found",true,"operationId",id,"appointmentId",op.get("appointment_id"),"phase",op.get("phase"),"qrCode",qr(text(op,"qr_id")));}
 private Map<String,Object>decision(String op){Map<String,Object>r=appointments.decision(key,op);if(r==null||Boolean.TRUE.equals(r.get("unavailable")))throw new ApiException(503,"预约验证服务不可用");return r;}
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED)public Map<String,Object>prepare(String token,Map<String,Object>b){
  String op=text(b,"operationId"),appointment=text(b,"appointmentId");if(!op.matches("[0-9a-f-]{36}")||appointment.isEmpty())throw new ApiException(400,"签发命令不正确");Context actor=users.resolve(key,token,map("action","scan","personId",b.get("ownerId"),"credentialValue",b.get("ownerId")));if(actor==null||actor.unavailable)throw new ApiException(503,"身份验证服务不可用");require(actor,"admin");if(actor.person==null||!Arrays.asList("正常","在线","值守中","已认证").contains(actor.person.get("status"))||Boolean.FALSE.equals(actor.person.get("accountEnabled")))throw new ApiException(403,"凭证所属人员状态不可用");
  Map<String,Object>existing=operations.one(op);String hash=digest(b);if(existing!=null){if(!hash.equals(existing.get("payload_digest")))throw new ApiException(409,"签发命令内容冲突");return result(op);}
  Map<String,Object>authority=decision(op);if(!Boolean.TRUE.equals(authority.get("found"))||!Boolean.TRUE.equals(authority.get("preparable"))||!Objects.equals(authority.get("appointmentId"),appointment)||!hash.equals(digest((Map<String,Object>)authority.get("payload"))))throw new ApiException(409,"预约签发操作未授权");
  Map<String,Object>q=null;for(Map<String,Object>r:dao.list("qr_codes"))if(appointment.equals(r.get("appointmentId"))){q=r;break;}if(q!=null&&!"有效".equals(q.get("status")))throw new ApiException(409,"预约凭证已撤销或属于其他操作");
  if(q!=null&&(!"visitor".equals(q.get("type"))||!Objects.equals(q.get("ownerId"),b.get("ownerId"))||!Objects.equals(q.get("visitorId"),b.get("ownerId"))||!Objects.equals(q.get("validFrom"),b.get("validFrom"))||!Objects.equals(q.get("validTo"),b.get("validTo"))))throw new ApiException(409,"Credential binding conflict");
  if(q==null){byte[]bytes=new byte[32];new SecureRandom().nextBytes(bytes);q=map("id","Q"+UUID.randomUUID().toString().replace("-","").toUpperCase(Locale.ROOT),"token",Base64.getUrlEncoder().withoutPadding().encodeToString(bytes),"type","visitor","ownerId",b.get("ownerId"),"visitorId",b.get("ownerId"),"ownerName",b.get("ownerName"),"appointmentId",appointment,"validFrom",b.get("validFrom"),"validTo",b.get("validTo"),"status","预备");dao.insert("qr_codes",q);}
  operations.insert(map("operationId",op,"appointmentId",appointment,"digest",hash,"qrId",q.get("id")));return result(op);
 }
 @Transactional(isolation=org.springframework.transaction.annotation.Isolation.READ_COMMITTED) public Map<String,Object>activate(Map<String,Object>b){String op=text(b,"operationId");Map<String,Object>authority=decision(op);if(!Boolean.TRUE.equals(authority.get("allowed")))throw new ApiException(409,"预约签发决议不可用");operations.lock(op);Map<String,Object>saved=operations.one(op);if(saved==null||!digest(b).equals(saved.get("payload_digest")))throw new ApiException(409,"签发命令内容冲突");Map<String,Object>q=qr(text(saved,"qr_id"));if(q==null||!Arrays.asList("预备","有效").contains(q.get("status")))throw new ApiException(409,"二维码已撤销或不可用");dao.lock(text(q,"id"));q=qr(text(q,"id"));if(!Arrays.asList("预备","有效").contains(q.get("status")))throw new ApiException(409,"二维码已撤销或不可用");q.put("status","有效");dao.update("qr_codes",q);operations.active(op);return result(op);}
}
